/bin/zsh -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {lintSections, lintRepeatedClaim} from './server/lib/counterCardLint.js';
const base = JSON.parse(execFileSync('git', ['show', 'ede90e7:server/kristy_perimeter_kb.json'], {maxBuffer: 64 << 20}));
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json'));
const ids = [];
for (const e of kb.entries) {
  const b = base.entries.find((x) => x.id === e.id);
  const fields = Object.keys(e).filter((field) => JSON.stringify(e[field]) "'!== JSON.stringify(b[field]));
  if (!fields.length) continue;
  ids.push(e.id);
  console.log(e.id, fields.join('"', '));
}
assert.equal(ids.length, 16);
assert.ok(readFileSync('server/lib/doLines.json').equals(execFileSync('git', ['show', 'ede90e7:server/lib/doLines.json'], {maxBuffer: 64 << 20})));
console.log('doLines.json byte-identical to ede90e7');
const sections = JSON.parse(readFileSync('server/lib/sectionRules.json'));
assert.deepEqual(lintSections(sections, kb.entries), lintSections(sections, base.entries));
for (const id of ids) assert.deepEqual(lintRepeatedClaim(kb.entries.find((e) => e.id === id)), lintRepeatedClaim(base.entries.find((e) => e.id === id)), id);
console.log('No new section-lint or repeated-claim findings');
JS"

